use vstd::prelude::*;

verus! {

    /// Given a non-empty array of 8-bit signed integers `x`,
    /// returns a 2-element array `[min, max]` such that:
    /// 1. `min <= max`
    /// 2. For every element `x[k]`, `min <= x[k] <= max`.
    /// 3. `min` and `max` both appear in `x`.
    fn getdomain(x: Vec<i8>) -> (result: Vec<i8>)
        requires
            x.len() > 0,
        ensures
            result.len() == 2,
            result[0] <= result[1],
            forall|k: usize| k < x.len() ==> result[0] <= x[k] && x[k] <= result[1],
            exists|k: usize| k < x.len() && x[k] == result[0],
            exists|k: usize| k < x.len() && x[k] == result[1],
    {
        // Initialize min and max to the first element
        let mut mn: i8 = x[0];
        let mut mx: i8 = x[0];
        // We have covered index 0, so start at 1
        let mut i: usize = 1;

        while i < x.len()
            invariant
                // i ranges over [1, x.len()]
                1 <= i <= x.len(),
                // Invariant ordering
                mn <= mx,
                // For every seen index, values lie between mn and mx
                forall|k: usize| k < i ==> mn <= x[k] && x[k] <= mx,
                // mn and mx both appear among the first i elements
                exists|k: usize| k < i && x[k] == mn,
                exists|k: usize| k < i && x[k] == mx,
            decreases
                x.len() - i,
        {
            let v: i8 = x[i];
            // Update the minimum if needed
            if v < mn {
                mn = v;
                // After lowering mn, still mn <= mx
                assert(mn <= mx);
            }
            // Update the maximum if needed
            if v > mx {
                mx = v;
                // After raising mx, still mn <= mx
                assert(mn <= mx);
            }
            i = i + 1;
        }

        // Build the 2-element result
        let result = vec![mn, mx];
        result
    }

}

